// Specter.Internal — NT / hostch bridge (implementation).

#include "pch-il2cpp.h"

#define WIN32_LEAN_AND_MEAN
#include <Windows.h>

#include "platform/nt.h"
#include "platform/log.h"
#include "platform/hostch-rva.h"   // generated by wine-hostch/emit-hostch-rva.sh

namespace specter::nt {

// HostchSpawnThread signature (ntdll, non-exported):
//   NTSTATUS WINAPI HostchSpawnThread(HANDLE *handle, ULONG magic,
//                                     PRTL_THREAD_START_ROUTINE start, void *param);
using RtlThreadStart = LONG (NTAPI *)(void *);
using HostchSpawnFn  = LONG (NTAPI *)(HANDLE *, unsigned long, RtlThreadStart, void *);

#if SPECTER_HOSTCH_SPAWN_RVA == 0
static HostchSpawnFn resolve() { return nullptr; }   // not baked yet
#else
static HostchSpawnFn resolve()
{
    HMODULE ntdll = GetModuleHandleW(L"ntdll.dll");
    if (!ntdll) return nullptr;
    return reinterpret_cast<HostchSpawnFn>(
        reinterpret_cast<uintptr_t>(ntdll) + SPECTER_HOSTCH_SPAWN_RVA);
}
#endif

bool spawn_hidden(DWORD (WINAPI *proc)(LPVOID), void *arg)
{
    HostchSpawnFn fn = resolve();
    if (!fn) {
        log::error("nt::spawn_hidden: HostchSpawnThread unresolved "
                   "(hostch-rva.h not baked, or ntdll not loaded)");
        return false;
    }

    HANDLE handle = nullptr;
    LONG status = fn(&handle, SPECTER_HOSTCH_SPAWN_MAGIC,
                     reinterpret_cast<RtlThreadStart>(proc), arg);
    if (status < 0) {
        log::error("nt::spawn_hidden: HostchSpawnThread failed (status=0x%08lX)",
                   static_cast<unsigned long>(status));
        return false;
    }
    if (handle) CloseHandle(handle);
    return true;
}

}  // namespace specter::nt
